import{_ as a}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as n,o as e,af as i}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const u=JSON.parse('{"title":"MiniMax Agent 术语表","description":"不教操作。先分清 Agent / Code / Hub / Design / Mini-Agent，再理解 Lightning、Pro 和 Agent Team。","frontmatter":{"title":"MiniMax Agent 术语表","description":"不教操作。先分清 Agent / Code / Hub / Design / Mini-Agent，再理解 Lightning、Pro 和 Agent Team。","domain":"product","tags":["coding-agent"],"role":"glossary"},"headers":[],"relativePath":"zh/products/minimax-agent/minimax-agent-glossary.md","filePath":"zh/products/minimax-agent/minimax-agent-glossary.md","lastUpdated":1787110548000}'),r={name:"zh/products/minimax-agent/minimax-agent-glossary.md"};function o(s,t,d,g,l,m){return e(),n("div",null,[...t[0]||(t[0]=[i(`<h1 id="minimax-agent-术语表" tabindex="-1">MiniMax Agent 术语表 <a class="header-anchor" href="#minimax-agent-术语表" aria-label="Permalink to &quot;MiniMax Agent 术语表&quot;">​</a></h1><p>不教操作，只解释「为什么这些名字会撞」。选哪个产品面看 <a href="./">学习地图</a>。</p><h2 id="概念关系" tabindex="-1">概念关系 <a class="header-anchor" href="#概念关系" aria-label="Permalink to &quot;概念关系&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>厂商 MiniMax</span></span>
<span class="line"><span>├── 通用工作台 MiniMax Agent（网页）</span></span>
<span class="line"><span>│   ├── 模式：Lightning / Pro</span></span>
<span class="line"><span>│   ├── 协作：Agent Team（Leader / Worker / Verifier）</span></span>
<span class="line"><span>│   ├── 扩展：Skill</span></span>
<span class="line"><span>│   └── 站内入口：MaxHermes / MaxClaw</span></span>
<span class="line"><span>├── 桌面编程 MiniMax Code        ← 不是本目录</span></span>
<span class="line"><span>├── 创作 MiniMax Design（英文 About 仍写 Hub）</span></span>
<span class="line"><span>├── 视频 Hailuo / 语音 Audio / 角色 星野·Talkie</span></span>
<span class="line"><span>└── 开放平台 API + Token Plan</span></span></code></pre></div><h2 id="都叫-minimax-agent-的东西" tabindex="-1">都叫 MiniMax / Agent 的东西 <a class="header-anchor" href="#都叫-minimax-agent-的东西" aria-label="Permalink to &quot;都叫 MiniMax / Agent 的东西&quot;">​</a></h2><table tabindex="0"><thead><tr><th>名字</th><th>是什么</th><th>在哪用</th></tr></thead><tbody><tr><td><strong>MiniMax Agent</strong></td><td>通用长程智能体工作台</td><td>agent.minimaxi.com / agent.minimax.io</td></tr><tr><td>MiniMax Code</td><td>桌面端 AI Agent 应用</td><td><a href="https://agent.minimaxi.com/docs/code/welcome" target="_blank" rel="noreferrer">welcome</a></td></tr><tr><td>MiniMax Hub</td><td>英文 About 里的一级产品名</td><td>当前 <code>hub.minimaxi.com</code> 加载 Design</td></tr><tr><td>MiniMax Design</td><td>多模态创作平台 / 画布</td><td>design.minimaxi.com</td></tr><tr><td>Hailuo / 海螺视频</td><td>视频生成产品</td><td>hailuoai.com</td></tr><tr><td>MiniMax Audio</td><td>语音与音乐</td><td>minimaxi.com/audio</td></tr><tr><td>星野</td><td>沉浸式智能体社区</td><td>xingyeai.com</td></tr><tr><td>Talkie</td><td>星野海外对应</td><td>talkie-ai.com</td></tr><tr><td>Mini-Agent</td><td>开放平台示例项目</td><td>GitHub MiniMax-AI/Mini-Agent</td></tr><tr><td>MaxHermes</td><td>Agent 站内「云端助手」入口</td><td>changelog 2026-04-16</td></tr><tr><td>MaxClaw</td><td>Agent 站内设置 / 渠道 / 人设入口</td><td>changelog 2026-04-11</td></tr><tr><td>Token Plan</td><td>订阅与额度</td><td>厂商站 Product nav</td></tr><tr><td>MiniMax M2 / M3</td><td>驱动模型，不是产品面</td><td>新闻与首页；机制见 <a href="https://llm.zenheart.site/chapters/" target="_blank" rel="noreferrer">Learn LLM</a></td></tr></tbody></table><p><strong>不是官方产品名，正文不要当事实写：</strong></p><ul><li>「MiniMax Agent 就是 Code 的网页版」——官方把桌面端单独更名为 Code。</li><li>「Hub 等于 Agent」——Hub 与 Design 对齐，不与 Agent 对齐。</li><li>把 Mini-Agent 示例仓写成产品下载地址。</li></ul><h2 id="minimax-agent-是什么-为什么需要" tabindex="-1">MiniMax Agent 是什么 / 为什么需要 <a class="header-anchor" href="#minimax-agent-是什么-为什么需要" aria-label="Permalink to &quot;MiniMax Agent 是什么 / 为什么需要&quot;">​</a></h2><p><strong>是什么：</strong> 网页上的通用智能体，接收目标，拆步骤，交付文件或页面。官方对照的是「靠谱的人」，不是补全框。</p><p><strong>为什么需要：</strong> 对话助手停在问答。Agent 要在长程任务里规划、调用工具、做测试、给出可打开的结果。<a href="https://www.minimaxi.com/news/minimax-agent" target="_blank" rel="noreferrer">靠谱</a> 把「Code is cheap，show me the requirement」写成生产关系变化。</p><p><strong>不是什么：</strong> 不是本机 IDE，不是 Hailuo 的套皮，不是星野。</p><h2 id="lightning-和-pro" tabindex="-1">Lightning 和 Pro <a class="header-anchor" href="#lightning-和-pro" aria-label="Permalink to &quot;Lightning 和 Pro&quot;">​</a></h2><p><strong>是什么：</strong> 同一产品上的两种模式，不是两个产品。</p><p><strong>为什么需要：</strong> <a href="https://www.minimaxi.com/news/minimax-m2" target="_blank" rel="noreferrer">M2 新闻</a> 把「又贵又慢」写成当时 Agent 产品的普遍问题。Lightning 保短任务速度，Pro 保长程质量。</p><p><strong>区别：</strong></p><table tabindex="0"><thead><tr><th></th><th>Lightning</th><th>Pro</th></tr></thead><tbody><tr><td>官方场景</td><td>问答、轻搜索、轻代码</td><td>研究、全栈、PPT、报告、网页</td></tr><tr><td>代价</td><td>长程交付容易不够</td><td>短任务可能过重</td></tr></tbody></table><h2 id="agent-team" tabindex="-1">Agent Team <a class="header-anchor" href="#agent-team" aria-label="Permalink to &quot;Agent Team&quot;">​</a></h2><p><strong>是什么：</strong> 主 Agent 牵头的多 Agent 系统。官方角色是 Leader、Worker、Verifier。用户仍只发一条消息。</p><p><strong>为什么需要：</strong> 单 Agent 既当选手又当裁判；长任务会提前停、会越做越偏、在 IM 里无法秒回。Team 把拆分、并行、验收变成系统行为。</p><p><strong>不是什么：</strong> 不是「多开几个聊天窗口」。也不是 Code 文档里的每一个子 Agent 开关都自动等于网页 Team。</p><p>官方还写了 Team Engine 状态：<code>producing</code> / <code>verifying</code> / <code>done</code>。这是设计描述，不是你要输入的命令。</p><h2 id="skill" tabindex="-1">Skill <a class="header-anchor" href="#skill" aria-label="Permalink to &quot;Skill&quot;">​</a></h2><p><strong>是什么：</strong> 可安装、可复用的领域流程。市场在 <a href="https://agent.minimaxi.com/skills" target="_blank" rel="noreferrer">skills</a>。</p><p><strong>为什么需要：</strong> 角色扮演不等于角色分工。官方 Team 文把工具、上下文、记忆、Skill 列为分工的四个维度。没有 Skill，每次都要从头教流程。</p><p><strong>与插件的区别：</strong> 技能市场是 Agent 网页可打开的页面。插件市场首发说明写在 MiniMax Code 更新里。两套扩展不要抄成一张表。</p><h2 id="hub-和-design" tabindex="-1">Hub 和 Design <a class="header-anchor" href="#hub-和-design" aria-label="Permalink to &quot;Hub 和 Design&quot;">​</a></h2><p><strong>是什么：</strong> 创作向产品。画布、分镜、成片、本地素材。</p><p><strong>为什么单独写：</strong> 英文 About 仍把 <strong>MiniMax Hub</strong> 列为一级产品；中文 About 写 <strong>MiniMax Design</strong>；<code>hub.minimaxi.com</code> 打开后是 Design。两份官方页打架时，本站同时引用，落地页以 Design 为准。</p><p><strong>不是什么：</strong> 不是 MiniMax Agent 的别名。</p><h2 id="相关页面" tabindex="-1">相关页面 <a class="header-anchor" href="#相关页面" aria-label="Permalink to &quot;相关页面&quot;">​</a></h2><ul><li><a href="./">学习地图</a></li><li><a href="./minimax-agent.html">教程</a></li><li><a href="./minimax-agent-cookbook.html">Cookbook</a></li><li><a href="./minimax-agent-cheatsheet.html">速查表</a></li></ul>`,32)])])}const M=a(r,[["render",o]]);export{u as __pageData,M as default};
